<?php
require 'config/database.php';require 'includes/functions.php';$title='Reports';$rows=$pdo->query("SELECT *,quantity*unit_cost AS stock_value FROM products WHERE is_archived=0 ORDER BY stock_value DESC")->fetchAll();$units=0;$value=0;$low=0;foreach($rows as $r){$units+=$r['quantity'];$value+=$r['stock_value'];if($r['quantity']<=$r['reorder_level'])$low++;}$movement=$pdo->query("SELECT type,COALESCE(SUM(quantity),0) units FROM stock_transactions GROUP BY type")->fetchAll();$tot=['IN'=>0,'OUT'=>0];foreach($movement as $m)$tot[$m['type']]=$m['units'];require 'includes/header.php';?>
<section class="heading"><div><small>INSIGHTS &amp; EXPORTS</small><h1>Inventory reports</h1><p>Current stock, valuation and movement summary.</p></div><button class="btn primary" onclick="window.print()">⇩ Print / Save PDF</button></section><section class="metrics report-metrics"><article><label>Total inventory value</label><b class="value"><?=money($value)?></b><small>Quantity × unit cost</small></article><article><label>Total units on hand</label><b><?=number_format($units)?></b><small>Across <?=count($rows)?> products</small></article><article><label>Products to reorder</label><b><?=$low?></b><small>At or below reorder level</small></article><article><label>Units received / issued</label><b><?=number_format($tot['IN'])?> / <?=number_format($tot['OUT'])?></b><small>Lifetime transaction totals</small></article></section><section class="panel"><div class="panel-head"><div><h2>Stock valuation report</h2><p>Current quantity and estimated cost value per product.</p></div><span class="pill bluepill"><?=count($rows)?> items</span></div><?php if(!$rows):?><div class="empty"><p>Add products to build your report.</p><a class="btn primary" href="product_form.php">Add product</a></div><?php else:?><div class="scroll"><table><thead><tr><th>PRODUCT</th><th>SKU</th><th>CATEGORY</th><th>QUANTITY</th><th>UNIT COST</th><th>STOCK VALUE</th><th>STATUS</th></tr></thead><tbody><?php foreach($rows as $r):$isLow=$r['quantity']<=$r['reorder_level'];?><tr><td><b><?=e($r['name'])?></b></td><td><?=e($r['sku'])?></td><td><?=e($r['category']?:'—')?></td><td><?=$r['quantity']?></td><td><?=money($r['unit_cost'])?></td><td><b><?=money($r['stock_value'])?></b></td><td><span class="pill <?=$isLow?'warning':'good'?>"><?=$isLow?'Reorder':'Healthy'?></span></td></tr><?php endforeach;?></tbody><tfoot><tr><td colspan="3"><b>TOTAL</b></td><td><b><?=number_format($units)?></b></td><td>—</td><td><b><?=money($value)?></b></td><td></td></tr></tfoot></table></div><?php endif;?></section><div class="note"><b>ⓘ About this report</b><p>Inventory valuation uses current quantity × unit cost. Use Print / Save PDF to export a printable report.</p></div><?php require 'includes/footer.php';?>